import hashlib,json,sys
from pathlib import Path
b=Path(__file__).resolve().parent
sys.path.insert(0,str(b/'runtime/code/src'))
from riskprop.stage_0_5_b1_isolation import install_guard
guard=install_guard(b)
tests=[]
for value in sys.argv[1:]:
    try:
        with open(value,'rb') as f:f.read(1)
    except PermissionError:tests.append(dict(path=value,rejected_before_content=True))
    else:raise AssertionError('denied_path_was_opened')
import numpy,pandas,pyarrow,pytest
deps={}
for m in [numpy,pandas,pyarrow,pytest]:
    p=Path(m.__file__);deps[m.__name__]=dict(version=m.__version__,entry_sha256=hashlib.sha256(p.read_bytes()).hexdigest())
result=dict(expected_negative_probes=tests,passed=len(tests)==3,audit=guard,dependency_fingerprints=deps,python_version=sys.version,
    dependency_timing='Post-analysis environment observation; does not prove all dependencies/DLLs immutable before and after',source_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest())
(b/'guard_probe_result.json').write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8')
assert len(guard['denied'])==len(tests)==3
